import React, { useContext } from 'react';
import ReactHtmlParser from 'react-html-parser';
import AppContext from '../contexts/AppContext';
import TrimesterProgressBar from '../components/TrimesterProgressBar';
import SummaryHighlights from '../components/SummaryHighlights';

const Summary: React.FC = () => {
  const appContext = useContext(AppContext);
  const { stage_info, summary, rtl } = appContext.data ? appContext.data : '';
  if (appContext.data) {

    return (
      <>
        <div className={`summary-page ${rtl ? 'rtl' : ''}`}>
          <div className="sideMargins">
            <h1>
              <div className="celebrate" />
              <div className="weeksContainerOuter">
                <div className="weeksContainer">{ReactHtmlParser(summary.preg_week_string)}</div>
              </div>
            </h1>

            <TrimesterProgressBar
              currentPregWeek={stage_info.preg_week}
              maxPregWeek={summary.preg_max_week}
            />
            <div className="trimesterText spacer">{summary.trimester_text}</div>
            {summary.to_go_text && (
              <div className="togoText spacerLg bodyText">
                <div>{ReactHtmlParser(summary.to_go_text)}</div>
                <div>{ReactHtmlParser(summary.your_month_text)}</div>
              </div>
            )}
          </div>

          {summary.content ? (
            <SummaryHighlights
              iconAltText={summary.lightbulb_alt_text}
              heading={summary.heading}
              content={summary.content}
            />
          ) : <div>&nbsp;</div>}
        </div>
      </>
    );
  }
  return <></>;
};

export default Summary;
