import React, { useState, useEffect } from 'react';
import axios from 'axios';
//import { DFPSlotsProvider, DFPManager } from '../third-party/react-dfp/lib';

// define types
type ContextProps = {
  loading: boolean;
  data: any;
  fetchData: () => void;
};

// create context
const AppContext = React.createContext<Partial<ContextProps>>({});

// create provider
const AppProvider: React.FC = ({ children }) => {
  // store all provider data in the state
  //const [dfpLoadCalled, setDfpLoadCalled] = useState(false);
  const [loading, setLoading] = useState(true);
  const [data, setData]: [any, any] = useState(null);
  type MyWindow = typeof window & {
    sampleStageJsonUrl: string;
    stageData: any;
  };
  // create provider update methods
  const fetchData = (): void => {
    console.log('fetchData() hit');
    // if the data is in the stageData variable, use that. Otherwise, get data from sample json file
    if ((window as MyWindow).stageData) {
      setData((window as MyWindow).stageData);
      setLoading(false);
    } else {
      axios.get((window as MyWindow).sampleStageJsonUrl).then(res => {
        setData(res.data);
        setLoading(false);
      });
    }
  };

  // fetch initial data
  // this might done somewhere else (you might want to fetch the data after some validation)
  useEffect(() => {
    fetchData();
  }, []);

  // Wait for data before calling load on react-dfp
  // useEffect(() => {
  //   let globalTargetParams = null;
  //   if (data && data.ad_info.ad_target_params) {
  //     globalTargetParams = data.ad_info.ad_target_params;
  //   }
  //   if (!dfpLoadCalled && globalTargetParams) {
  //     DFPManager.setTargetingArguments(globalTargetParams);
  //     DFPManager.load();
  //     setDfpLoadCalled(true);
  //   }
  // }, [data, loading, dfpLoadCalled]);

  return (
    <AppContext.Provider
      value={{
        // expose values
        loading,
        data,
        // expose fetch method
        fetchData
      }}
    >
      {children}
      {/* {data && data.ad_info.ad_target_params && (
        <DFPSlotsProvider
          autoLoad={false}
          dfpNetworkId={data.ad_info.dfp_network_id}
          singleRequest
          collapseEmptyDivs
          targetingArguments={data.ad_info.ad_target_params}
        >
          {children}
        </DFPSlotsProvider>
      )} */}
    </AppContext.Provider>
  );
};

export default AppContext;
export { AppProvider };
