import React, { useRef, useEffect } from 'react';
import { RouteComponentProps, withRouter } from 'react-router-dom';

const PageChange = ({ location }: RouteComponentProps): JSX.Element => {
  const previousPage = useRef('');
  const currentPage = useRef('');

  type MyWindow = typeof window & {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    notifyPageChange: any;
  };

  useEffect(() => {
    previousPage.current = currentPage.current;
    // Trailing slash? Remove it.
    if (location.pathname.substr(location.pathname.length - 1) === '/') {
      currentPage.current = location.pathname.substr(0, location.pathname.length - 1);
    } else {
      currentPage.current = location.pathname;
    }
    if (currentPage.current !== previousPage.current) {
      window.scrollTo(0, 0);
    }
    if ((window as MyWindow).notifyPageChange) {
      // notify page change
      (window as MyWindow).notifyPageChange(currentPage.current);
    }
  });

  // Component renders nothing
  return <></>;
};

export default withRouter(PageChange);
