import React, { useContext } from 'react';
import ReactHtmlParser from 'react-html-parser';
import FetalDevDetail from '../components/FetalDevDetail';
import AppContext from '../contexts/AppContext';
//import MediumRectangleAd from '../components/ads/MediumRectangleAd';

const YourBaby: React.FC = () => {
  const appContext = useContext(AppContext);
  const { your_baby, rtl } = appContext.data ? appContext.data : '';

  return (
    <div className={`your-baby-page spacerLg ${rtl ? 'rtl' : ''}`}>
      {appContext.data && (
        <div>
          <FetalDevDetail
            image_url={your_baby.image_url}
            hotspot_tip_label={your_baby.hotspot_tip_label}
            hotspots={your_baby.hotspots}
            image_alt_text={your_baby.image_alt_text}
          />
          <div className="fetalDevContent sideMargins spacerLg bodyText">
            {ReactHtmlParser(your_baby.content)}
          </div>
        </div>
      )}

      {/*<MediumRectangleAd />*/}
    </div>
  );
};

export default YourBaby;
