import React from 'react';
import { HashRouter, Route, Switch, Redirect } from 'react-router-dom';
import './App.css';

// Global components
//import Header from './components/Header';
//import FooterWrapper from './components/Footer';

// Interior pages
import Summary from './templates/Summary';
import YourBaby from './templates/YourBaby';
import BabySize from './templates/BabySize';
import YourBody from './templates/YourBody';
import { AppProvider } from './contexts/AppContext';

import PageChange from './components/util/PageChange';

type MyWindow = typeof window & {
  startingScreen: string;
};

/* support entering on different screen based on startingScreen variable */
let { startingScreen } = window as MyWindow;

if (
  startingScreen !== '/your-baby' &&
  startingScreen !== '/your-body' &&
  startingScreen !== '/baby-size'
) {
  startingScreen = 'summary';
}

function App(): React.ReactElement {
  return (
    <HashRouter>
      <AppProvider>
        {/*<Header />*/}
        {/* wrapper div with 'page' creates whitespace in mobile app for leaderboard */}
        {/* <div className="page"> */}
        <Switch>
          <Route exact path="/summary" component={Summary} />
          <Route path="/your-baby" component={YourBaby} />
          <Route path="/baby-size" component={BabySize} />
          <Route path="/your-body" component={YourBody} />
          <Redirect exact from="/" to={startingScreen} />
          {/*{/!*Need a 404 page? Make 404 component and assign here*!/}
              {/!*Default, sends non matching URLs to homepage*!/}*/}
          <Route component={Summary} />
        </Switch>
        {/* </div> */}
        {/*<FooterWrapper />*/}
      </AppProvider>
      {/* Handles resetting page to top on navigation (typical website behavior)*/}
      <PageChange />
    </HashRouter>
  );
}

export default App;
