import React, { useCallback } from 'react';
import shortid from 'shortid';

type fetalDevData = {
  image_url: string;
  image_alt_text: string;
  hotspot_tip_label: string;
  hotspots: Array<Hotspot>;
  hardcoded_short_id?: string;
};

type Hotspot = {
  id: number;
  x: number;
  y: number;
  caption_text: string;
};

const FetalDevDetail: React.FC<fetalDevData> = fetalDevData => {
  const zoomMultplier = 3; // src image must be large enough to zoom to this size. Container is max width of 400, so with a zoomMultiplier of 3, image must be at least 1200x1200
  const [zoomIconClass, setZoomIconClass] = React.useState('zoomInOut bgZoomIn');
  const [captionText, setCaptionText] = React.useState(fetalDevData.hotspot_tip_label);
  const [zoomContainerStyle, setZoomContainerStyle] = React.useState({});
  const [zoomImgStyle, setZoomImgStyle] = React.useState({});
  const [containerHeight, setContainerHeight] = React.useState(0);

  /* We explicitly the height in the style attribute so it won't grow with the zoomed image
  This assumes the image is square
   */
  const fetalDevContainer = useCallback(node => {
    if (node !== null) {
      setContainerHeight((window.innerWidth > 400 ? 400 : window.innerWidth));
    }
  }, []);

  const zoomAndUpdateCaption = (x: number, y: number, caption: string): void => {
    if (zoomIconClass.includes('bgZoomIn')) {
      // Zoom in on hotspot and update the caption
      const hotspotAsPercentage = {
        x: x * 100,
        y: y * 100
      };

      let leftPosPercent = 0; // how far image will be shifted left on zoom
      let topPosPercent = 0; // how far image will be shift up on zoom
      const zoomedCenter = 50 / zoomMultplier; // where the center of the container will be when zoomed (as percentage)
      const positionAdjustment = 50;
      
      if (hotspotAsPercentage.x > zoomedCenter) {
        leftPosPercent = (hotspotAsPercentage.x * zoomMultplier) - positionAdjustment;
      } else if (hotspotAsPercentage.x < zoomedCenter / 2) {
        leftPosPercent = 0;
      } else {
        leftPosPercent = positionAdjustment - (hotspotAsPercentage.x * zoomMultplier);
      }
      
      if (hotspotAsPercentage.y > zoomedCenter) {
        topPosPercent = (hotspotAsPercentage.y * zoomMultplier) - positionAdjustment;
      } else if (hotspotAsPercentage.y < zoomedCenter / 2) {
        topPosPercent = 0;
      } else {
        topPosPercent = positionAdjustment - (hotspotAsPercentage.y * zoomMultplier);
      }
      
      setZoomIconClass('zoomInOut bgZoomOut');
      setZoomContainerStyle({ height: containerHeight, width: '100%' });
      setZoomImgStyle({
        width: `${zoomMultplier * 100}%`,
        position: 'absolute',
        left: `-${leftPosPercent}%`,
        top: `-${topPosPercent}%`
      });
      setCaptionText(caption);
    } else {
      // zoom out and show default caption
      setZoomImgStyle({ width: '100%' });
      setZoomIconClass('zoomInOut bgZoomIn');
      setCaptionText(fetalDevData.hotspot_tip_label);
    }
  };

  return (
    <div className="fetalDevImageSection">
      <div className="fetalDevDetail" id="fetalDevDetail" style={zoomContainerStyle} ref={fetalDevContainer}>
        <div className="fetalDevImgContainer" style={zoomImgStyle}>
          <img src={fetalDevData.image_url} width="1200" height="1200" alt={fetalDevData.image_alt_text} />
          <div id="hotSpotContainer" className="hotSpotContainer">
            {fetalDevData.hotspots.map(hotspot => {
              const styles = {
                top: `${hotspot.y * 100}%`,
                left: `${hotspot.x * 100}%`
              };

              return (
                <div className="hotspot" style={styles} key={`id-${fetalDevData.hardcoded_short_id ? fetalDevData.hardcoded_short_id : shortid.generate()}`}>
                  <div
                    className={zoomIconClass}
                    onClick={(): void => zoomAndUpdateCaption(hotspot.x, hotspot.y, hotspot.caption_text)}
                  />
                </div>
              );
            })}
          </div>
        </div>
      </div>

      <div className="fetalDevDetailText">
        <div id="defaultText">{captionText}</div>
        <div id="zoomText" />
      </div>
    </div>
  );
};

export default FetalDevDetail;
