import React, { useState, useEffect } from 'react';
import CSS from 'csstype';

type TrimesterBarData = {
  currentPregWeek: number;
  maxPregWeek: number;
};

type TrimesterWeeksData = {
  trimester1WeeksComplete: number;
  trimester2WeeksComplete: number;
  trimester3WeeksComplete: number;
  trimester1TotalWeeks: number;
  trimester2TotalWeeks: number;
  trimester3TotalWeeks: number;
};

/* Take a total number of weeks pregnant, and calculate the number of weeks completed in each trimester
   Returns an object with the weeks complete in each trimester and the total weeks in each trimester */
const getWeeksCompleteInEachTrimester = (
  weeksPregnant: number,
  trimester3End: number
): TrimesterWeeksData => {
  const trimester1Start = 0;
  // For a standard 40-week pregnancy, week 14 is the 1st week of 2nd trimester and week 28 is the 1st week of 3rd trimester
  // For 41-week pregnancy, week 16 is the 1st week of 2nd trimester and week 29 is the 1st week of 3rd trimester
  // we want to show a "notch" of progress when you're in the first week of the trimester, so setting the values -1
  const trimester2Start = trimester3End === 41 ? 15 : 13;
  const trimester3Start = trimester3End === 41 ? 28 : 27;
  const trimester1TotalWeeks = trimester2Start - trimester1Start; // number of weeks in the 1st trimester
  const trimester2TotalWeeks = trimester3Start - trimester2Start; // number of weeks in the 2nd trimester
  const trimester3TotalWeeks = trimester3End - trimester3Start; // number of weeks in the 3rd trimester
  const trimester1WeeksComplete =
    weeksPregnant < trimester2Start ? weeksPregnant : trimester1TotalWeeks;
  let trimester2WeeksComplete = 0;
  let trimester3WeeksComplete = 0;

  // Calculate the number of weeks complete in the 2nd and 3rd trimesters for the current stage
  if (weeksPregnant >= trimester2Start) {
    if (weeksPregnant >= trimester3Start) {
      trimester2WeeksComplete = trimester2TotalWeeks;
      if (weeksPregnant > trimester3End) {
        // do not allow weeks complete to be larger than the total weeks in the trimester
        trimester3WeeksComplete = trimester3End - trimester3Start;
      } else {
        trimester3WeeksComplete = weeksPregnant - trimester3Start;
      }
    } else {
      trimester2WeeksComplete = weeksPregnant - trimester2Start;
    }
  }
  return {
    trimester1WeeksComplete,
    trimester2WeeksComplete,
    trimester3WeeksComplete,
    trimester1TotalWeeks,
    trimester2TotalWeeks,
    trimester3TotalWeeks
  };
};

const getPercentageComplete = (completed: number, total: number): number =>
  (completed / total) * 100;

const TrimesterProgressBar: React.FC<TrimesterBarData> = trimesterBarData => {
  const percentSign = '%';
  const triWeeks = getWeeksCompleteInEachTrimester(
    trimesterBarData.currentPregWeek,
    trimesterBarData.maxPregWeek
  );
  const [trimester1ProgressStyle, setTrimester1ProgressStyle] = useState<CSS.Properties>({
    width: 0
  });
  const [trimester2ProgressStyle, setTrimester2ProgressStyle] = useState<CSS.Properties>({
    width: 0
  });
  const [trimester3ProgressStyle, setTrimester3ProgressStyle] = useState<CSS.Properties>({
    width: 0
  });
  const animationSpeed = 500;

  useEffect(() => {
    // set the progress for each trimester as a percentage (in timeout for animation)
    const timer1 = window.setTimeout(() => {
      setTrimester1ProgressStyle({
        width:
          getPercentageComplete(triWeeks.trimester1WeeksComplete, triWeeks.trimester1TotalWeeks) +
          percentSign
      });
    }, 1);
    const timer2 = window.setTimeout(() => {
      setTrimester2ProgressStyle({
        width:
          getPercentageComplete(triWeeks.trimester2WeeksComplete, triWeeks.trimester2TotalWeeks) +
          percentSign
      });
    }, animationSpeed);
    const timer3 = window.setTimeout(() => {
      setTrimester3ProgressStyle({
        width:
          getPercentageComplete(triWeeks.trimester3WeeksComplete, triWeeks.trimester3TotalWeeks) +
          percentSign
      });
    }, animationSpeed * 2);

    // cleanup to avoid memory leak warning "Can't perform a React state update on an unmounted component"
    return (): void => {
      clearTimeout(timer1);
      clearTimeout(timer2);
      clearTimeout(timer3);
    };
  }, [
    triWeeks.trimester1TotalWeeks,
    triWeeks.trimester1WeeksComplete,
    triWeeks.trimester2TotalWeeks,
    triWeeks.trimester2WeeksComplete,
    triWeeks.trimester3TotalWeeks,
    triWeeks.trimester3WeeksComplete
  ]);

  return (
    <div className="pregProgressBar spacerSm">
      <div id="progressTrimester1" className="triProgressBar">
        <span style={trimester1ProgressStyle} />
      </div>
      <div id="progressTrimester2" className="triProgressBar">
        <span style={trimester2ProgressStyle} />
      </div>
      <div id="progressTrimester3" className="triProgressBar">
        <span style={trimester3ProgressStyle} />
      </div>
    </div>
  );
};
export default TrimesterProgressBar;
export { getWeeksCompleteInEachTrimester, getPercentageComplete };
