import React, { useContext } from 'react';
import ReactHtmlParser from 'react-html-parser';
import AppContext from '../contexts/AppContext';
import BabySizeMeasurements from '../components/BabySizeMeasurements';

const BabySize: React.FC = () => {
  const appContext = useContext(AppContext);
  const { baby_size, stage_info, rtl } = appContext.data ? appContext.data : '';
  return (
    <>
      {appContext.data !== undefined && appContext.data !== null && (
        <div className={`baby-size-page ${rtl ? 'rtl' : ''}`}>
          <div className="fruitTitle bodyText sideMargins">
            {ReactHtmlParser(baby_size.baby_size_title)}
          </div>
          <div className="sectionDivider">
            <div className="angle" />
            <div className="sectionIcon">
              <img
                src={baby_size.fruit_image_url}
                width="260"
                height="260"
                alt={baby_size.fruit_image_alt_text}
              />
            </div>
          </div>

          {stage_info.preg_week > 7 ? (
            <BabySizeMeasurements
              fruit_height={baby_size.fruit_height}
              fruit_height_label={baby_size.fruit_height_label}
              fruit_height_unit={baby_size.fruit_height_unit}
              fruit_ruler_alt_text={baby_size.fruit_ruler_alt_text}
              fruit_ruler_label={baby_size.fruit_ruler_label}
              fruit_scale_alt_text={baby_size.fruit_scale_alt_text}
              fruit_weight={baby_size.fruit_weight}
              fruit_weight_label={baby_size.fruit_weight_label}
              fruit_weight_unit={baby_size.fruit_weight_unit}
            />
          ) : <div className="shadedSection" />}
        </div>
      )}
    </>
  );
};

export default BabySize;
